package br.com.minhagibiteca.catalog.presentation;
import jakarta.validation.constraints.*; import java.util.List; import java.util.UUID;
public class EditionForm { private UUID publisherId,seriesId; private List<UUID> workIds = List.of(), creatorIds = List.of(); @NotBlank(message="Informe o título da edição.") @Size(max=240) private String title; @Size(max=60) private String editorialNumber; @Size(max=120) private String variant; @Size(max=32) private String isbn; @Min(1800) @Max(2100) private Integer publicationYear; @Size(max=60) private String format; @Size(max=2000) private String notes;
 public UUID getPublisherId(){return publisherId;} public void setPublisherId(UUID v){publisherId=v;} public UUID getSeriesId(){return seriesId;} public void setSeriesId(UUID v){seriesId=v;} public List<UUID> getWorkIds(){return workIds;} public void setWorkIds(List<UUID> v){workIds=v;} public List<UUID> getCreatorIds(){return creatorIds;} public void setCreatorIds(List<UUID> v){creatorIds=v;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getEditorialNumber(){return editorialNumber;} public void setEditorialNumber(String v){editorialNumber=v;} public String getVariant(){return variant;} public void setVariant(String v){variant=v;} public String getIsbn(){return isbn;} public void setIsbn(String v){isbn=v;} public Integer getPublicationYear(){return publicationYear;} public void setPublicationYear(Integer v){publicationYear=v;} public String getFormat(){return format;} public void setFormat(String v){format=v;} public String getNotes(){return notes;} public void setNotes(String v){notes=v;} }
